852	\begin{algorithmic}[1]
853	\REQUIRE DAG topology $\mathcal{T}$, gold-label availability $G \in \{\textsc{yes}, \textsc{no}\}$
854	\ENSURE Recommended method $M$, risk level $R$
855	\STATE
856	\STATE \textbf{Step 1: Assess risk level}
