858	    \STATE $R \gets \textsc{Low}$ \COMMENT{$|\text{bias}| < 0.04$ for all $C$}
859	\ELSIF{$\mathcal{T} \in \{\text{Conf., Med., Coll., Front-door}\}$}
860	    \STATE $R \gets \textsc{Medium}$ \COMMENT{bounded bias, no sign reversal}
861	\ELSE
